import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@tiips/db";

// Helper to validate session
async function validateAdminSession() {
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== "ADMIN") {
        return null;
    }
    return session;
}

export async function GET(
    req: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        if (!await validateAdminSession()) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { id } = await params;
        const policy = await prisma.insurancePolicy.findUnique({
            where: { id }
        });

        if (!policy) {
            return NextResponse.json({ error: "Policy not found" }, { status: 404 });
        }

        return NextResponse.json(policy);
    } catch (error) {
        console.error("Get policy error:", error);
        return NextResponse.json({ error: "Failed to fetch policy" }, { status: 500 });
    }
}

export async function PUT(
    req: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        if (!await validateAdminSession()) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { id } = await params;
        const body = await req.json();

        // Extract updatable fields
        const {
            name,
            description,
            clauseType,
            rate,
            minPremium,
            currency,
            isActive
        } = body;

        const updatedPolicy = await prisma.insurancePolicy.update({
            where: { id },
            data: {
                name,
                description,
                clauseType,
                rate: rate !== undefined ? parseFloat(rate) : undefined,
                minPremium: minPremium !== undefined ? parseFloat(minPremium) : undefined,
                currency,
                isActive: isActive !== undefined ? Boolean(isActive) : undefined
            }
        });

        return NextResponse.json(updatedPolicy);
    } catch (error) {
        console.error("Update policy error:", error);
        return NextResponse.json({ error: "Failed to update policy" }, { status: 500 });
    }
}

export async function DELETE(
    req: Request,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        if (!await validateAdminSession()) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const { id } = await params;

        // Check if policy has orders
        const usageCount = await prisma.order.count({
            where: { policyId: id }
        });

        if (usageCount > 0) {
            // Soft delete instead of hard delete if used
            await prisma.insurancePolicy.update({
                where: { id },
                data: { isActive: false }
            });
            return NextResponse.json({ message: "Policy deactivated (used in orders)" });
        }

        // Hard delete if not used
        await prisma.insurancePolicy.delete({
            where: { id }
        });

        return NextResponse.json({ message: "Policy deleted successfully" });
    } catch (error) {
        console.error("Delete policy error:", error);
        return NextResponse.json({ error: "Failed to delete policy" }, { status: 500 });
    }
}
